
const DATA = {};

DATA.origins = {"orphan":{"name":"Otherworld Orphan (the child brought back)","desc":"You were picked up by the Search and Rescue Corps in a dead other world. The member who brought you back wrote in the report: \"Orphans encountered must be brought back. — Order, no exceptions.\"","stats":{"hp":14,"atk":1,"def":1,"spd":1,"will":2}},"branch":{"name":"Branch House","desc":"Both your parents serve in a branch. You grew up hearing applause from the stage, and you knew from childhood that the applause was not for you.","stats":{"hp":4,"atk":3,"def":3,"spd":1,"will":0}},"frontier":{"name":"Frontline Orphan","desc":"Your homeland was lost in an unrecorded war. In the ruins you learned your first lesson: survive first, ask why later.","stats":{"hp":6,"atk":3,"def":1,"spd":3,"will":1}},"void":{"name":"Born of the Void","desc":"You opened your eyes inside a stretch of void. The Third Eternal found you before your power could spread, sealed you, and brought you back to the Organization.","stats":{"hp":0,"atk":2,"def":0,"spd":2,"will":4}}};

DATA.schools = {"sword":{"name":"Heng Sword Arts","core":"Guard","color":"#d8b45c","bonus":{"def":3},"abilities":["sword_guard","sword_still"],"desc":"Heng is the core — the unchanging is the master, the changing is the tool. It excels not at killing but at holding. As long as the sword-bearer's will stands, the sword force does not scatter."},"bow":{"name":"Heng Bow Arts","core":"Far","color":"#7fd8ff","bonus":{"spd":3},"abilities":["bow_early","bow_return"],"desc":"He does not aim. In his view the arrow is already there; drawing the bow only takes it back."},"blade":{"name":"Heng Blade Arts","core":"Short","color":"#b48cff","bonus":{"atk":3},"abilities":["blade_vein","blade_silent"],"desc":"The shortest of the five lines, and the only one he hardly taught. His reason, in his own words: \"The dagger — teach it, and things go wrong easily.\""},"spear":{"name":"Heng Spear Arts","core":"Pierce","color":"#e0a04b","bonus":{"atk":2,"def":1},"abilities":["spear_line","spear_pierce"],"desc":"Piercing is the core. The spear travels in a straight line; the farther, the heavier. One thrust can pierce the entire front."},"axe":{"name":"Heng Axe Arts","core":"Heavy","color":"#e0544b","bonus":{"hp":10,"atk":1},"abilities":["axe_break","axe_quake"],"desc":"Axe, hammer, dagger-axe, halberd — he created and perfected these as well, under the collective name Heng Arts."}};

DATA.oaths = {"record":{"name":"To Remember Them","bonus":{"will":2},"desc":"\"Because the ones who made noise — I remembered them for them.\" — Will +2"},"guard":{"name":"Leave No One Behind","bonus":{"def":3},"desc":"\"Bring back any orphan you find.\" — Defense +3"},"pursue":{"name":"I Will Catch That Silhouette","bonus":{"atk":3},"desc":"Where that back passed, the sword force had not yet dispersed. — Strength +3"},"wander":{"name":"I Want to See the World","bonus":{"spd":3},"desc":"\"This Siyuan isn't dead, but he likes to wander.\" — Speed +3"}};

