DATA.arena = {"name":"Arena","intro":"At the center of the Organization is a non-material energy body of infinite resources. Around it lies the Arena, which branch members treat as a place where you can fight as you please.","tiers":[{"id":"t1","name":"First Layer · Training Ground","glyph":"Martial","unlockLv":1,"desc":"Standard fare the branch uses to convert Honor. Suited to new members.","enemies":["cultist","cultguard","cult_acolyte"],"statScale":0.8,"expScale":0.85,"honor":60},{"id":"t2","name":"Second Layer · Otherworld Rift","glyph":"Rift","unlockLv":4,"desc":"Things the Search and Rescue Corps brought back from other worlds sometimes crawl out of the rifts again.","enemies":["cultlord","cult_zealot","cult_torturer","hydra","nuke_unit"],"statScale":1,"expScale":1.05,"honor":140},{"id":"t3","name":"Third Layer · Outskirts of the Ancient Godbone Domain","glyph":"Bone","unlockLv":8,"desc":"A place no one but an Eternal dares enter. You keep to the outer edge.","enemies":["cult_bishop","cult_choir","altar_guard","grave_warden","voidking","enemy_gen"],"statScale":1.22,"expScale":1.3,"honor":300},{"id":"t4","name":"Fourth Layer · Godslayer Training Ground","glyph":"Slay","unlockLv":12,"desc":"A practice ground for the God-Slaying Corps. The sign reads: serious injury at your own risk.","enemies":["cult_saint","cult_executor","destroygod","deathgod","clockdemon"],"statScale":1.45,"expScale":1.6,"honor":560},{"id":"t5","name":"Fifth Layer · Beneath the Stage","glyph":"Stage","unlockLv":16,"desc":"No list, no record. It is said someone once met inside it something they should never have met.","enemies":["abyss_maw","false_prophet","grand_hierophant","cult_army","xleader","wuxiang"],"statScale":1.72,"expScale":2,"honor":1000}],"streakBonus":0.12};

