DATA.sideQuests = [{"id":"q_sweep","chapter":0,"npc":"Branch · Bookkeeper","name":"Chores of the Branch","brief":"The branch has piled up a batch of jobs no one would take. Go clear the outermost outposts first. It does not need to be fought well. It only needs to be clean.","obj":{"kind":"killAny","count":6},"award":{"exp":220,"honor":300,"mat":{"mat_cult":2}}},{"id":"q_firstblood","chapter":0,"npc":"Branch · Veteran","name":"The First Rule of Survival","brief":"\"The new want to win. The old want to live.\" Fill your own blood once, then come find me.","obj":{"kind":"fullHp","count":1},"award":{"exp":180,"honor":240,"items":[["kit_std",3]]}},{"id":"q_ironwill","chapter":1,"npc":"Armory · Keeper","name":"Iron and Will","brief":"Go and get yourself some proper gear. Do not use the defective issue from the branch. They break on the one blow that matters most.","obj":{"kind":"weapons","count":3},"award":{"exp":320,"honor":420,"mat":{"mat_blade":3}}},{"id":"q_recruit2","chapter":1,"npc":"Personnel · Duty Officer","name":"A Party Cannot Be Just You","brief":"The Heng Organization does not keep men who walk alone. Go recruit two who can walk out of the branch gates with you.","obj":{"kind":"allies","count":2},"award":{"exp":360,"honor":500,"items":[["kit_mass",2]]}},{"id":"q_cult","chapter":2,"npc":"Front · Runner","name":"The Breathing Statue","brief":"Those hooded things in the east carve living people into pillars and set them at the crossroads. Clear fourteen of them.","obj":{"kind":"tag","tag":"cult","count":14},"award":{"exp":700,"honor":900,"mat":{"mat_cult":6}}},{"id":"q_chapter3","chapter":3,"npc":"Archive · Scribe","name":"Copy the Names Down","brief":"Finish the Second Tale. We need to know how the second Heng died. That will be useful to everyone.","obj":{"kind":"chapterDone","index":1},"award":{"exp":900,"honor":1100,"mat":{"mat_memory":2}}},{"id":"q_blade","chapter":3,"npc":"Armory · Smith","name":"The Severed Edge","brief":"I want eight broken sword blades. Do not ask me what for — ask, and I still will not say.","obj":{"kind":"material","mat":"mat_blade","count":8},"award":{"exp":1000,"honor":1200,"weapons":["blade_silent"]},"unlockWeapon":"blade_silent"},{"id":"q_arena5","chapter":4,"npc":"Arena · Bookkeeper","name":"Arena Tally","brief":"Win five matches in the Boundless Hall. Consecutive wins double experience. A loss, and it never happened.","obj":{"kind":"arenaWins","count":5},"award":{"exp":1400,"honor":1800,"mat":{"mat_crystal":4}}},{"id":"q_level","chapter":5,"npc":"Training Ground · Instructor","name":"Train the Body Properly","brief":"Train to Lv.14. Do not rely on luck. Rely on training.","obj":{"kind":"level","count":14},"award":{"exp":500,"honor":2000,"items":[["coin_amp",2]]}},{"id":"q_ice","chapter":5,"npc":"Front · Scout","name":"The Unmelting Snow","brief":"The fourth's territory is frosting over. Bring back six shards of ice crystal. I want to confirm whether that is true permafrost.","obj":{"kind":"material","mat":"mat_crystal","count":6},"award":{"exp":1600,"honor":1900,"mat":{"mat_memory":2}}},{"id":"q_chapter6","chapter":6,"npc":"Stage · Recorder","name":"The Sixth Chapter's Ending","brief":"Finish the Fifth Tale. The section on the Void Lord is blank in the archive — fill it in.","obj":{"kind":"chapterDone","index":4},"award":{"exp":2200,"honor":2600,"mat":{"mat_void":3}}},{"id":"q_star","chapter":7,"npc":"Observatory · Night Watch","name":"What Falls Behind","brief":"The battlefield of a Star Darling leaves stardust behind. Collect five portions. Do not touch them with bare hands.","obj":{"kind":"material","mat":"mat_star","count":5},"award":{"exp":2600,"honor":3000,"weapons":["bow_long"],"unlockWeapon":"bow_long"}},{"id":"q_ally","chapter":7,"npc":"Personnel · Duty Officer","name":"Six Names","brief":"Your roster needs six Eternals. It is not a number — it is proof that the Heng Organization still lives.","obj":{"kind":"eternals","count":6},"award":{"exp":3200,"honor":4200,"items":[["void_orb",2]]}},{"id":"q_arena15","chapter":8,"npc":"Arena · Bookkeeper","name":"Regular","brief":"Win fifteen more. The Arena welcomes you — it has never made anyone miserable. It simply lets no one go.","obj":{"kind":"arenaWins","count":20},"award":{"exp":3800,"honor":5200,"mat":{"mat_memory":4}}},{"id":"q_boss1","chapter":9,"npc":"Stage · Recorder","name":"First Time on the Stage","brief":"Defeat an Eternal on the stage. Not a drill — the stage.","obj":{"kind":"bossWins","count":1},"award":{"exp":4200,"honor":6000,"mat":{"mat_seal":1},"weapons":["relic_sheath"],"unlockWeapon":"relic_sheath"}},{"id":"q_chapter10","chapter":10,"npc":"Archive · Scribe","name":"Before the Tenth Chapter","brief":"Finish the ninth chapter. An Enforcer-type Eternal... our internal records on this differ greatly.","obj":{"kind":"chapterDone","index":8},"award":{"exp":4800,"honor":6000,"mat":{"mat_memory":3}}},{"id":"q_mat30","chapter":10,"npc":"Junk Shop · Owner","name":"The Junk Shop's Big Order","brief":"Bring me thirty pieces of material. Anything — shards, blades, crystal dust, ash. I do not pick.","obj":{"kind":"materials","count":30},"award":{"exp":5200,"honor":7000,"items":[["kit_mass",5],["coin_amp",3]]}},{"id":"q_boss3","chapter":11,"npc":"Stage · Recorder","name":"Three Eternals","brief":"Defeat three Eternals on the stage. They will not hold back because you are young.","obj":{"kind":"bossWins","count":3},"award":{"exp":6000,"honor":8000,"mat":{"mat_seal":3},"weapons":["eternal_hour"],"unlockWeapon":"eternal_hour"}},{"id":"q_final","chapter":11,"npc":"[Heng] itself","name":"After the Twelfth Chapter","brief":"Finish the final chapter. Then you will find this side quest was never a side quest.","obj":{"kind":"chapterDone","index":11},"award":{"exp":9999,"honor":12000,"items":[["kit_mass",9]],"title":"Keeper of Heng"}}];

