DATA.assists = [{"id":"a_siyuan","ever":"siyuan","chapter":"siyuan","stages":["The Cult God-King"],"ever$":true,"name":"Siyuan","title":"Third Eternal · Support","lv":34,"hp":320,"atk":30,"def":24,"spd":30,"coins":6,"moves":["m_jab","m_hook","m_kick","m_spinkick","m_slash","m_still","m_guard"],"weapon":"relic_sheath","join":"\"You take the two flanks. The one in the middle — I'll take him.\"","leave":"He sheathed the sword as if nothing had happened. \"Remember: this isn't me saving you. This is what the Organization is supposed to do.\"","quote":"An ordinary body, endless power. Day to day he keeps only the third layer of the seal."},{"id":"a_heng","ever":"heng","chapter":"heng","stages":["Half a Day"],"name":"Heng","title":"First Eternal · Support","lv":30,"hp":300,"atk":28,"def":26,"spd":24,"coins":6,"moves":["m_jab","m_hook","m_slash","m_still","m_guard","m_dodge"],"weapon":"sword_guard","join":"\"The unchanging is the master, the changing is the tool. — I only do the first half.\"","leave":"He did not look at you. He only drew the blade tip back. \"The rest is your affair.\"","quote":"Everything he practiced in his life, gathered into one sword."}];
