DATA.assistRoster = [{"id":"r_heng","ever":"heng","name":"Heng","chapter":"heng","label":null,"title":"First Eternal","lv":26,"hp":300,"atk":26,"def":22,"spd":24,"coins":6,"weapon":"sword_std","moves":["m_jab","m_hook","m_slash","m_still","m_guard","m_dodge"],"join":"\"Fall back. This stretch is mine.\"","leave":"He did not look at anyone as he sheathed the sword, as if he had merely finished what was due.","quote":"Everything of a lifetime, gathered at last into one sword."},{"id":"r_liguangyang_disciple","ever":"liguangyang","name":"Li Guangyang","chapter":"heng","label":"·The first's disciple · only successor","title":"The first Eternal's only successor","lv":18,"hp":180,"atk":16,"def":14,"spd":22,"coins":5,"weapon":"sword_std","moves":["m_jab","m_kick","m_slash","m_guard"],"join":"\"Master said, when you cannot hold on, do one small thing first.\"","leave":"He put the Master's sword into its sheath. The sound was faint.","quote":"Hatred can be a discipline too — but that came much later.","stages":["One Direction"]},{"id":"r_liguangyang","ever":"liguangyang","name":"Li Guangyang","chapter":"liguangyang","label":null,"title":"Second Eternal","lv":30,"hp":320,"atk":30,"def":26,"spd":26,"coins":6,"weapon":"sword_std","moves":["m_jab","m_hook","m_slash","m_still","m_guard","m_feint"],"join":"\"Practice first. Practice until I can win without revenge.\"","leave":"He said little. He only wrote the date of the next campaign on the wall.","quote":"The second to be both Leader and Eternal.","stages":["One Man Clears One Hall"]},{"id":"r_siyuan_member","ever":"siyuan","name":"Siyuan","chapter":"siyuan","label":"·Eternal candidate (9th heir to the Heng Sword Arts prototype)","title":"Organization member · Ninth heir of the Sword Arts","lv":22,"hp":220,"atk":22,"def":18,"spd":28,"coins":6,"weapon":"leg_guard","moves":["m_jab","m_kick","m_spinkick","m_dodge","m_guard","m_feint"],"join":"\"Wait — I go first.\"","leave":"He wiped his hands on his clothes, as if he had done something he did not want seen.","quote":"At five he took apart an entire training ground, because he wanted to see where the pipes underneath led.","stages":["Four Months","Nine: The Time Without a Sword"]},{"id":"r_liyaohui_cand","ever":"liyaohui","name":"Li Yaohui","chapter":"siyuan","label":"·Eternal Candidate","title":"Eternal Reserve · Siyuan's disciple","lv":20,"hp":200,"atk":20,"def":20,"spd":30,"coins":5,"weapon":"blade_std","moves":["m_jab","m_stab","m_silent","m_dodge","m_feint","m_guard"],"join":"\"I can fight too. Don't stop me.\"","leave":"He wiped the blood off his face and asked when the next one was.","quote":"At eleven he deserted once; at thirteen his master caught him and brought him back. He was not punished.","stages":["The Traitor","A Duel Once a Day"]},{"id":"r_siyuan","ever":"siyuan","name":"Siyuan","chapter":"siyuan","label":null,"title":"Third Eternal","lv":34,"hp":320,"atk":30,"def":24,"spd":30,"coins":6,"weapon":"relic_sheath","moves":["m_jab","m_hook","m_kick","m_spinkick","m_slash","m_still","m_guard"],"join":"\"You take the two flanks. The one in the middle — I'll take him.\"","leave":"He sheathed the sword as if nothing had happened. \"This isn't me saving you. This is what the Organization is supposed to do.\"","quote":"An ordinary body, endless power. Day to day he keeps only the third layer of the seal.","stages":["The Cult God-King"]},{"id":"r_liyaohui","ever":"liyaohui","name":"Li Yaohui","chapter":"liyaohui","label":null,"title":"Fourth Eternal","lv":32,"hp":330,"atk":31,"def":30,"spd":30,"coins":6,"weapon":"sword_guard","moves":["m_jab","m_slash","m_still","m_hook","m_guard","m_dodge"],"join":"\"Step back. I have seen this thing before.\"","leave":"Ice shards fell from his cuff and melted on landing.","quote":"The eternal lord of frostcrystal. Uses every Heng art.","stages":["The Year He Was Eight: Defection","Extermination in Half a Day","Before the Heart"]},{"id":"r_siyuan_retired","ever":"siyuan","name":"Siyuan","chapter":"liyaohui","label":"(Retired)","title":"Third Eternal (retired)","lv":36,"hp":340,"atk":32,"def":26,"spd":32,"coins":6,"weapon":"relic_sheath","moves":["m_jab","m_slash","m_still","m_pierce","m_guard","m_dodge"],"join":"\"This is the last wave. When it's done, I go back to sleep.\"","leave":"He left faster than anyone, as if truly sleepy.","quote":"Long retired. He comes back now and then only because someone can't be handled.","stages":["The Last Battle Before Frostcrystal","Half a Day"]},{"id":"r_chengmoge_appr","ever":"chengmoge","name":"Cheng Moge","chapter":"liyaohui","label":"·Apprentice","title":"Disciple of Li Yaohui","lv":24,"hp":240,"atk":24,"def":20,"spd":26,"coins":5,"weapon":"sword_std","moves":["m_jab","m_hook","m_slash","m_guard","m_dodge"],"join":"\"Master said this Move must close clean. I'll try.\"","leave":"He wiped the sword three times before daring to put it away.","quote":"The identity plate hung at his neck — the first thing an Eternal ever gave him."},{"id":"r_chengmoge","ever":"chengmoge","name":"Cheng Moge","chapter":"chengmoge","label":null,"title":"Fifth Eternal","lv":34,"hp":340,"atk":32,"def":26,"spd":28,"coins":6,"weapon":"axe_std","moves":["m_jab","m_hook","m_chop","m_quake","m_guard","m_dodge"],"join":"\"I don't like war. But I will finish it.\"","leave":"He stowed his weapon and first went to look at the wounded.","quote":"At forty-seven, he killed the Destruction God-King and the Death God-King.","stages":["The Election","After the Stage","The Battlefield at Ten"]},{"id":"r_liyaohui_active","ever":"liyaohui","name":"Li Yaohui","chapter":"chengmoge","label":null,"title":"Fourth Eternal","lv":33,"hp":335,"atk":31,"def":28,"spd":30,"coins":6,"weapon":"sword_guard","moves":["m_jab","m_slash","m_still","m_guard","m_dodge"],"join":"\"I'll teach you what it means to close a stance.\"","leave":"He stood still, watched his disciple sheathe the sword, and nodded.","quote":"Took a disciple at twenty-nine; retired and passed the seat at forty-two.","stages":["The God-King of Destruction","The God-King of Death"]},{"id":"r_xiaoran_trainee","ever":"xiaoran","name":"Xiao Ran","chapter":"chengmoge","label":"·Eternal Candidate (trainee)","title":"A candidate trained by three Eternals together","lv":28,"hp":280,"atk":28,"def":20,"spd":30,"coins":5,"weapon":"blade_silent","moves":["m_jab","m_stab","m_silent","m_slash","m_dodge","m_feint"],"join":"\"Watch it once more. This time I will keep up.\"","leave":"He stood still replaying that Move, and forgot to leave.","quote":"Of what Siyuan taught, he can mimic eighty-seven percent at a glance.","stages":["The Mission in the Stars"]},{"id":"r_xiaoran","ever":"xiaoran","name":"Xiao Ran","chapter":"xiaoran","label":null,"title":"Sixth Eternal","lv":38,"hp":380,"atk":36,"def":28,"spd":34,"coins":6,"weapon":"blade_silent","moves":["m_jab","m_stab","m_silent","m_slash","m_pierce","m_dodge"],"join":"\"This place is the Void. Don't stand behind me.\"","leave":"He raised a hand and gathered the leftover void, as if folding away an old coat.","quote":"1.17 million matches, not one win. At twenty he became the Sixth.","stages":["After 1,170,000 Times"]},{"id":"r_luolan_cand","ever":"luolan","name":"Luo Lan · Qian'an","chapter":"xiaoran","label":"·Eternal Candidate (branch member)","title":"[Heng] Organization member · Anomalous talent","lv":26,"hp":260,"atk":26,"def":18,"spd":34,"coins":5,"weapon":"sword_std","moves":["m_jab","m_kick","m_slash","m_dodge","m_feint","m_guard"],"join":"\"I practiced this Move on the back hill. Let me try.\"","leave":"He was breathing hard, but he kept watching where Siyuan had just been standing.","quote":"His talent is 128 times that of the Third Eternal."},{"id":"r_luolan","ever":"luolan","name":"Luo Lan · Qian'an","chapter":"luolan","label":null,"title":"Seventh Eternal","lv":38,"hp":380,"atk":36,"def":30,"spd":40,"coins":6,"weapon":"spear_std","moves":["m_jab","m_thrust","m_pierce","m_slash","m_dodge","m_feint"],"join":"\"Stay with me. Don't go more than three meters.\"","leave":"He looked back to confirm his comrades were still there, then took up his spear.","quote":"From pauper to Eternal, every step he took was looked down on by someone.","stages":["The Succession Ceremony","The Race That Devours Civilizations"]},{"id":"r_sihuiyan_young","ever":"sihuiyan","name":"Luo Lan · Sihuiyan","chapter":"luolan","label":"·Tempered With Siyuan","title":"The girl at Siyuan's side (not yet in office)","lv":22,"hp":230,"atk":22,"def":20,"spd":26,"coins":5,"weapon":"sword_std","moves":["m_jab","m_slash","m_guard","m_dodge","m_feint"],"join":"\"Grandfather said I can't hold up the sky. I don't need to — I only need to stand firm when you tire.\"","leave":"She stood still and memorized everyone's positions.","quote":"At ten she begged Siyuan to teach her the Heng arts. Siyuan only patted her head."},{"id":"r_sihuiyan","ever":"sihuiyan","name":"Luo Lan · Sihuiyan","chapter":"sihuiyan","label":null,"title":"Eighth Eternal · First to Ascend","lv":42,"hp":420,"atk":40,"def":34,"spd":34,"coins":6,"weapon":"bow_long","moves":["m_shot","m_volley","m_star","m_guard","m_dodge","m_feint"],"join":"\"The fallen gods all stand on my side.\"","leave":"She nodded toward somewhere — no one was there.","quote":"The first of the Eternals to become a god. She stayed in the Domain of Ancient Divine Remains until one hundred ninety-six.","stages":["Dark Horse","The Domain of Ancient Godbones","One Hundred and Ninety-Six Years in the Domain","The Seat Left Empty After the Selection"]},{"id":"r_luolan_active","ever":"luolan","name":"Luo Lan · Qian'an","chapter":"sihuiyan","label":null,"title":"Seventh Eternal (Father)","lv":40,"hp":400,"atk":38,"def":32,"spd":40,"coins":6,"weapon":"spear_line","moves":["m_jab","m_thrust","m_pierce","m_spinkick","m_dodge"],"join":"\"Stand behind me. This is not a discussion.\"","leave":"He glanced at his daughter and left without a word.","quote":"The first battle between Eternal and Eternal was father against daughter.","stages":["Father and Daughter Draw Blades"]},{"id":"r_xiaoran_active","ever":"xiaoran","name":"Xiao Ran","chapter":"sihuiyan","label":null,"title":"Sixth Eternal","lv":40,"hp":400,"atk":38,"def":30,"spd":34,"coins":6,"weapon":"blade_silent","moves":["m_jab","m_silent","m_stab","m_slash","m_dodge"],"join":"\"Everyone, stop. This is the Organization.\"","leave":"He pushed the blade back into its sheath. The sound was faint.","quote":"The moment he struck, that father-daughter farce stopped."},{"id":"r_xiaoyahui","ever":"xiaoyahui","name":"Xiao Yahui","chapter":"xiaoyahui","label":null,"title":"Ninth Eternal · First Enforcer Type","lv":44,"hp":440,"atk":42,"def":32,"spd":42,"coins":6,"weapon":"spear_line","moves":["m_jab","m_thrust","m_pierce","m_rule","m_dodge","m_feint"],"join":"\"The terms are clear. Execute now.\"","leave":"He finished the record before looking up.","quote":"Trained in Siyuan's inner world for 666125 years — years, not age.","stages":["666,125 Years","The Second Comprehensive War","Forcing Out the Final Form"]},{"id":"r_xiaoran_father","ever":"xiaoran","name":"Xiao Ran","chapter":"xiaoyahui","label":null,"title":"Sixth Eternal (Father)","lv":42,"hp":420,"atk":40,"def":30,"spd":34,"coins":6,"weapon":"blade_silent","moves":["m_jab","m_silent","m_pierce","m_slash","m_dodge"],"join":"\"Don't push yourself. Stand where I can see you.\"","leave":"Only after confirming his son was unhurt did he turn.","quote":"When two Lords of the Void stand shoulder to shoulder, almost no one on the field can get close.","stages":["Father and Son"]},{"id":"r_jiangmoran_cand","ever":"jiangmoran","name":"Jiang Moran","chapter":"xiaoyahui","label":"·Eternal Candidate (superstar)","title":"[Heng] Organization Superstar","lv":30,"hp":300,"atk":30,"def":22,"spd":36,"coins":5,"weapon":"fist_bare","moves":["m_jab","m_hook","m_kick","m_spinkick","m_dodge","m_feint"],"join":"\"The camera is here. I'll try to make it look good.\"","leave":"He bowed to empty air, as if taking a curtain call.","quote":"At twenty-three, the stars recognized two people at once for the first time — him and his sister.","stages":["Forcing Out the Final Form"]},{"id":"r_jiangmoran","ever":"jiangmoran","name":"Jiang Moran","chapter":"jiangmoran","label":null,"title":"Tenth Eternal · Superstar","lv":44,"hp":440,"atk":42,"def":30,"spd":40,"coins":6,"weapon":"fist_bare","moves":["m_jab","m_hook","m_spinkick","m_star","m_dodge","m_feint"],"join":"\"I'm enough for the West District alone. Go cover somewhere else.\"","leave":"He looked up at the stars and smiled once.","quote":"At one hundred eighty-six, he held the West District on his own.","stages":["The Stars' Acknowledgement","The Same Night","Holding the West District Alone"]},{"id":"r_liyaohui_veteran","ever":"liyaohui","name":"Li Yaohui","chapter":"jiangmoran","label":null,"title":"Fourth Eternal","lv":42,"hp":420,"atk":40,"def":32,"spd":30,"coins":6,"weapon":"sword_guard","moves":["m_jab","m_slash","m_still","m_guard","m_dodge"],"join":"\"Request approved. The west district is yours.\"","leave":"After the battle he personally placed the reward in the child's hands.","quote":"He is the current lord of frostcrystal. He will not age."},{"id":"r_mang_butler","ever":"mang","name":"Mang","chapter":"jiangmoran","label":"·Steward of the Siyuan family (not yet in office)","title":"Siyuan's only servant · family steward","lv":26,"hp":260,"atk":24,"def":28,"spd":30,"coins":5,"weapon":"knuckle","moves":["m_jab","m_hook","m_guard","m_bulwark","m_dodge","m_feint"],"join":"\"My master told me to watch you. I will watch.\"","leave":"He withdrew quietly to one side, as if he had never appeared.","quote":"The dial runs at his neck: tick... tick...","stages":["Iron Curtain"]},{"id":"r_mang","ever":"mang","name":"Mang","chapter":"mang","label":null,"title":"Eleventh Eternal · Personnel Manager Type","lv":36,"hp":400,"atk":30,"def":38,"spd":30,"coins":5,"weapon":"knuckle","moves":["m_jab","m_hook","m_guard","m_bulwark","m_rule","m_dodge"],"join":"\"I'm not good at fighting. But I'm very good at standing here.\"","leave":"He held the dial to his ear and listened, then tucked it into his collar.","quote":"Past five thousand, he no longer took revenge, no longer wandered. Only the butler remained.","stages":["Three Thousand Years","Corpses Everywhere","Kneeling Beneath the Sanctuary"]},{"id":"r_siyuan_guide","ever":"siyuan","name":"Siyuan","chapter":"mang","label":"(Retired)","title":"Third Eternal (retired) · the Namer","lv":44,"hp":420,"atk":40,"def":30,"spd":34,"coins":6,"weapon":"relic_sheath","moves":["m_jab","m_slash","m_still","m_pierce","m_guard","m_dodge"],"join":"\"You are Mang. Remember, I named you.\"","leave":"He set the fist form once more in the back yard and signaled the other to follow.","quote":"He granted the name, then taught for three thousand years.","stages":["The Back Courtyard"]},{"id":"r_final_heng","ever":"heng","name":"Heng","chapter":"final","label":"(First)","title":"First Eternal · the one on the statue","lv":48,"hp":480,"atk":46,"def":36,"spd":32,"coins":6,"weapon":"sword_std","moves":["m_jab","m_slash","m_still","m_hook","m_guard","m_dodge"],"join":"\"You filled this square. Good.\"","leave":"He withdrew into the shadow of the statue.","quote":"What he left behind was later called the Heng Sword Arts prototype.","stages":["The Twelfth's Slot","Wuxiang","Mirror-Self"]},{"id":"r_final_liguangyang","ever":"liguangyang","name":"Li Guangyang","chapter":"final","label":null,"title":"Second Eternal","lv":48,"hp":480,"atk":46,"def":36,"spd":32,"coins":6,"weapon":"sword_std","moves":["m_jab","m_hook","m_slash","m_still","m_guard","m_feint"],"join":"\"Hatred can be a discipline too. It took me thirty years to understand that.\"","leave":"He tucked the list into his coat.","quote":"He held the seat for twenty-seven years, and left it empty in the end."},{"id":"r_final_siyuan","ever":"siyuan","name":"Siyuan","chapter":"final","label":null,"title":"Third Eternal · Eternal Chief","lv":60,"hp":600,"atk":58,"def":44,"spd":40,"coins":8,"weapon":"relic_sheath","moves":["m_jab","m_slash","m_still","m_pierce","m_rule","m_guard","m_dodge"],"join":"\"Stand back. I make this sword strike. You watch.\"","leave":"His sheathing motion was exactly as it was forty years ago.","quote":"Ranked first among the Eternals. This body is only a double.","stages":["After the Retelling"]},{"id":"r_final_liyaohui","ever":"liyaohui","name":"Li Yaohui","chapter":"final","label":null,"title":"Fourth Eternal","lv":50,"hp":500,"atk":48,"def":38,"spd":32,"coins":7,"weapon":"sword_guard","moves":["m_jab","m_slash","m_still","m_pierce","m_guard","m_dodge"],"join":"\"I hold the front. You only move forward.\"","leave":"He stood at the very front and did not look back.","quote":"The current Sovereign of Ice Crystals."},{"id":"r_final_chengmoge","ever":"chengmoge","name":"Cheng Moge","chapter":"final","label":null,"title":"Fifth Eternal","lv":50,"hp":500,"atk":48,"def":36,"spd":30,"coins":7,"weapon":"axe_quake","moves":["m_jab","m_chop","m_quake","m_hook","m_guard","m_dodge"],"join":"\"I have killed two God-Kings. This one counts too.\"","leave":"He shouldered the axe and walked slowly back to the ranks.","quote":"At forty-seven, he killed the Destruction God-King and the Death God-King."},{"id":"r_final_xiaoran","ever":"xiaoran","name":"Xiao Ran","chapter":"final","label":null,"title":"Sixth Eternal","lv":52,"hp":520,"atk":50,"def":36,"spd":40,"coins":7,"weapon":"blade_silent","moves":["m_jab","m_silent","m_stab","m_pierce","m_rule","m_dodge"],"join":"\"The Void is mine. You strike what is solid.\"","leave":"He cleared the Void from the battlefield before leaving.","quote":"Eternal Power Ranking, Second.","stages":["Mirror-Self"]},{"id":"r_final_luolan","ever":"luolan","name":"Luo Lan · Qian'an","chapter":"final","label":null,"title":"Seventh Eternal","lv":50,"hp":500,"atk":48,"def":36,"spd":44,"coins":7,"weapon":"spear_line","moves":["m_jab","m_thrust","m_pierce","m_spinkick","m_dodge"],"join":"\"My talent is 128 times Siyuan's. Don't let me waste it.\"","leave":"He stood his spear on the ground and waited for others to go first.","quote":"From a pauper of {Lanwang} to the Seventh, it took him twenty-four years."},{"id":"r_final_sihuiyan","ever":"sihuiyan","name":"Luo Lan · Sihuiyan","chapter":"final","label":null,"title":"Eighth Eternal · First to Ascend","lv":52,"hp":520,"atk":50,"def":40,"spd":36,"coins":7,"weapon":"bow_long","moves":["m_shot","m_volley","m_star","m_rule","m_guard","m_feint"],"join":"\"What I brought is from the Godbone Domain. Stand firm.\"","leave":"She nodded again toward a direction where no one stood.","quote":"The first among the Eternals to become a god."},{"id":"r_final_xiaoyahui","ever":"xiaoyahui","name":"Xiao Yahui","chapter":"final","label":null,"title":"Ninth Eternal · Enforcement type","lv":52,"hp":520,"atk":52,"def":36,"spd":44,"coins":7,"weapon":"spear_line","moves":["m_jab","m_thrust","m_pierce","m_rule","m_dodge","m_feint"],"join":"\"This is execution, not revenge. The difference matters.\"","leave":"He finished the execution record before leaving the battlefield.","quote":"The first Eternal who often stayed among the lowest members.","stages":["Old Debts"]},{"id":"r_final_jiangmoran","ever":"jiangmoran","name":"Jiang Moran","chapter":"final","label":null,"title":"Tenth Eternal · Superstar","lv":52,"hp":520,"atk":50,"def":36,"spd":42,"coins":7,"weapon":"fist_bare","moves":["m_jab","m_hook","m_spinkick","m_star","m_dodge","m_feint"],"join":"\"I lend you the stars. Return them when you are done.\"","leave":"He looked up, as if to confirm those things in the sky were still there.","quote":"The 57th darling of the stars was his master — he himself was only one recognized by the stars."},{"id":"r_final_mang","ever":"mang","name":"Mang","chapter":"final","label":null,"title":"Eleventh Eternal · Personnel Manager Type","lv":48,"hp":520,"atk":44,"def":44,"spd":32,"coins":6,"weapon":"knuckle","moves":["m_jab","m_hook","m_guard","m_bulwark","m_rule","m_dodge"],"join":"\"I've brought everyone to where they should be. You can begin.\"","leave":"He counted the ranks and confirmed not one was missing.","quote":"The dial still runs. Tick... tick..."}];


