DATA.weaponJobs = {"fist_bare":"warrior","knuckle":"warrior","leg_guard":"warrior","sword_std":"warrior","sword_guard":"warrior","blade_std":"warrior","blade_silent":"warrior","spear_std":"warrior","spear_line":"warrior","axe_std":"warrior","axe_quake":"warrior","relic_sheath":"warrior","eternal_king":"warrior","eternal_hour":"warrior","staff_std":"mage","staff_seal":"mage","orb_frost":"mage","orb_void":"mage","kit_field":"healer","bow_std":"ranger","bow_long":"ranger","bow_short":"ranger","gun_hand":"gunner","gun_rifle":"gunner","gun_cannon":"gunner","drone_std":"mechanic","drone_heavy":"mechanic"};

DATA.weaponJobsExtra = {"staff_std":["healer"],"orb_frost":["healer"],"kit_field":["mechanic"]};

function weaponJobsOf(wid) {
const main = DATA.weaponJobs[wid];
const extra = (DATA.weaponJobsExtra && DATA.weaponJobsExtra[wid]) || [];
const list = [];
if (main) list.push(main);
extra.forEach(function (j) { if (list.indexOf(j) < 0) list.push(j); });
return list;
}
function weaponUsableBy(wid, jobId) {
if (!wid || !jobId) return true;

if (!DATA.weaponJobs[wid]) return true;
return weaponJobsOf(wid).indexOf(jobId) >= 0;
}
function jobWeapons(jobId) {
return Object.keys(DATA.weaponJobs).filter(function (w) { return weaponUsableBy(w, jobId); });
}

