DATA.affinity = (function () {
var T = DATA.moveTypes;
var dot = function (a, b) { return a[0]*b[0] + a[1]*b[1] + a[2]*b[2]; };
var norm = function (a) { return Math.sqrt(dot(a, a)); };
var out = {};
Object.keys(T).forEach(function (x) {
out[x] = {};
Object.keys(T).forEach(function (y) {
var v = dot(T[x].vec, T[y].vec) / (norm(T[x].vec) * norm(T[y].vec));
out[x][y] = Math.max(0, Math.min(1, v));
});
});
return out;
})();

